      secrets = [
        {
          name      = "ALPACA_CREDENTIALS"
          valueFrom = aws_secretsmanager_secret.runtime.arn
        }
      ]

      linuxParameters = {
        initProcessEnabled = true
      }

      logConfiguration = {
        logDriver = "awslogs"
        options = {
